declare r record; d text; o text; pr text[]; n int := 0;
  pairs text[][] := array[array[$q$<b>ابدأ منين؟</b><br>• جرّب المعاينة المجانية في أي كورس قبل ما تشترك.<br>• اختار الباقة اللي تناسبك (شهري، نص سنوي، سنوي) وكل الكورسات المسجلة تفتح لك.<br>• خلّص الكورس واستلم شهادتك تلقائي.$q$,$q$<b>من أين تبدأ؟</b><br>• جرّب المعاينة المجانية في أي دورة قبل الاشتراك.<br>• اختر الباقة المناسبة لك (شهرية، نصف سنوية، سنوية) لتُفتح لك جميع الدورات المسجلة.<br>• أتمّ الدورة واستلم شهادتك تلقائيًا.$q$],
array[$q$<b>🎁 اكسب شهور مجانية:</b> ابعت رابط الدعوة بتاعك لصحابك: لما <b>3 منهم يشتركوا</b> بتاخد <b>شهر مجاني</b> (ومرة كمان كل 6 شهور)، ولو وصلوا <b>10</b> بتاخد <b>6 شهور مجانًا</b>.$q$,$q$<b>🎁 احصل على أشهر مجانية:</b> أرسل رابط دعوتك إلى أصدقائك: عندما <b>يشترك 3 منهم</b> تحصل على <b>شهر مجاني</b> (ومرة أخرى كل 6 أشهر)، وإذا وصلوا إلى <b>10</b> تحصل على <b>6 أشهر مجانًا</b>.$q$],
array[$q$<b>🎁 شهور مجانية ليك:</b> ابعت رابط دعوتك لصحابك. لما 3 منهم يشتركوا بتاخد شهر مجاني (ومرة كمان كل 6 شهور)، ولو وصلوا 10 بتاخد 6 شهور مجانًا.$q$,$q$<b>🎁 أشهر مجانية لك:</b> أرسل رابط دعوتك إلى أصدقائك. عندما يشترك 3 منهم تحصل على شهر مجاني (ومرة أخرى كل 6 أشهر)، وإذا وصلوا إلى 10 تحصل على 6 أشهر مجانًا.$q$],
array[$q$نصيحة للبداية: افتح أي كورس وكمّل كل محاضرة لحد 50٪ على الأقل عشان المحاضرة اللي بعدها تفتح، ولما تخلّص الكورس كله شهادتك بتطلع تلقائي.$q$,$q$نصيحة للبداية: افتح أي دورة وشاهد 50٪ على الأقل من كل محاضرة لتُفتح المحاضرة التالية، وعند إتمام الدورة كاملةً تصدر شهادتك تلقائيًا.$q$],
array[$q$حسابك على منصة Biosyn Egypt جاهز. هنا هتلاقي كورسات مسجلة وتفاعلية في العلوم والطب والبايوانفورماتكس والبرمجة، بمحتوى عملي من متخصصين.$q$,$q$حسابك على منصة Biosyn Egypt جاهز. ستجد هنا دورات مسجلة وتفاعلية في العلوم والطب والمعلوماتية الحيوية والبرمجة، بمحتوى عملي يقدّمه متخصصون.$q$],
array[$q$باقتك الحالية «%» أطول من الباقة دي. تقدر تشترك فيها في آخر 7 أيام من اشتراكك الحالي (بيخلص %)، أو ترقّي لباقة أطول دلوقتي.$q$,$q$باقتك الحالية «%» أطول من هذه الباقة. يمكنك الاشتراك فيها في آخر 7 أيام من اشتراكك الحالي (ينتهي في %)، أو الترقية إلى باقة أطول الآن.$q$],
array[$q$الفريق بيراجع وصول المبلغ، وأول ما يتأكد هيتفعّل لك تلقائي ويوصلك إيميل بالتأكيد. ده عادة بياخد ساعات قليلة في أوقات العمل.$q$,$q$يراجع الفريق وصول المبلغ، وفور تأكيده سيُفعَّل لك تلقائيًا ويصلك بريد إلكتروني بالتأكيد. يستغرق ذلك عادةً ساعات قليلة في أوقات العمل.$q$],
array[$q$تقدر تفتحها وتحمّلها PDF أو تطبعها، وكمان تشاركها على LinkedIn. كل شهادة ليها رقم وكود QR عشان أي حد يتأكد إنها حقيقية.$q$,$q$يمكنك فتحها وتحميلها بصيغة PDF أو طباعتها، ومشاركتها على LinkedIn أيضًا. لكل شهادة رقم ورمز QR ليتمكن أي شخص من التحقق من صحتها.$q$],
array[$q$3 أصحاب يشتركوا من رابطك = شهر مجاني، و10 = 6 شهور مجانًا. انسخ رابطك من صفحة «شهر مجاني» في حسابك.$q$,$q$3 أصدقاء يشتركون عبر رابطك = شهر مجاني، و10 = 6 أشهر مجانًا. انسخ رابطك من صفحة «شهر مجاني» في حسابك.$q$],
array[$q$تقدمك في كل محاضرة وشهاداتك محفوظين. أول ما تجدّد، كل حاجة بترجع زي ما كانت وتكمّل من نفس النقطة.$q$,$q$تقدّمك في كل محاضرة وشهاداتك محفوظة. فور التجديد يعود كل شيء كما كان وتتابع من النقطة نفسها.$q$],
array[$q$المدة الجديدة بتبدأ بعد ما اشتراكك الحالي يخلص، فمفيش ولا يوم ضاع عليك. اشتراكك بقى ساري حتى <b>$q$,$q$تبدأ المدة الجديدة بعد انتهاء اشتراكك الحالي، فلن يضيع عليك أي يوم. أصبح اشتراكك ساريًا حتى <b>$q$],
array[$q$المبلغ هيرجع على نفس وسيلة الدفع خلال أيام العمل المعتادة للبوابة، وتم إلغاء تسجيلك في الكورس.$q$,$q$سيُعاد المبلغ إلى وسيلة الدفع نفسها خلال أيام العمل المعتادة للبوابة، وتم إلغاء تسجيلك في الدورة.$q$],
array[$q$كمّل: كل 3 أصحاب يشتركوا من رابطك = شهر مجاني (مرة كل 6 شهور)، ولما يوصلوا 10 = 6 شهور مجانًا.$q$,$q$استمر: كل 3 أصدقاء يشتركون عبر رابطك = شهر مجاني (مرة كل 6 أشهر)، وعندما يصلون إلى 10 = 6 أشهر مجانًا.$q$],
array[$q$وكمان: لو 3 من أصحابك اشتركوا من رابط دعوتك بتاخد شهر مجاني، يعني ممكن تكمّل من غير ما تدفع.$q$,$q$وأيضًا: إذا اشترك 3 من أصدقائك عبر رابط دعوتك تحصل على شهر مجاني، أي يمكنك المتابعة دون أن تدفع.$q$],
array[$q$تقدر تجدّد من دلوقتي، والمدة الجديدة بتبدأ بعد ما الحالية تخلص مباشرة، فمش هتخسر ولا يوم.$q$,$q$يمكنك التجديد من الآن، وستبدأ المدة الجديدة مباشرةً بعد انتهاء المدة الحالية، فلن تخسر أي يوم.$q$],
array[$q$نسخة PDF من الاتفاقية متاحة في لوحة المحاضر. لو عندك أي سؤال عن البنود رد على الإيميل ده.$q$,$q$نسخة PDF من الاتفاقية متاحة في لوحة المحاضر. إذا كان لديك أي سؤال عن البنود فردّ على هذه الرسالة.$q$],
