begin
  for r in select p.oid from pg_proc p join pg_namespace s on s.oid=p.pronamespace where s.nspname='public' and p.prokind='f' and pg_get_functiondef(p.oid) ~ '[؀-ۿ]' loop
    d := pg_get_functiondef(r.oid); o := d;
    foreach pr slice 1 in array pairs loop d := replace(d, pr[1], pr[2]); end loop;
    if d <> o then execute d; n := n + 1; end if;
  end loop;
  raise notice 'functions updated: %', n;
end $mig$;